import { 
  AppBar, Toolbar, Typography, Button, Box, IconButton, 
  Menu, MenuItem, Avatar, Divider, Slide, useScrollTrigger,
  Fade, Badge, Switch, styled, alpha, useTheme, Tooltip 
} from '@mui/material';
import { Link, useNavigate } from 'react-router-dom';
import { useState, useEffect, useRef } from 'react';
import { motion, useAnimation, AnimatePresence } from 'framer-motion';
import {
  Menu as MenuIcon,
  AccountCircle,
  Notifications,
  Settings,
  Logout,
  Brightness4,
  Brightness7,
  Search,
  ExpandMore,
  KeyboardArrowUp
} from '@mui/icons-material';

// Custom styled components with advanced effects
const GlassAppBar = styled(AppBar)(({ theme }) => ({
  background: `linear-gradient(
    135deg,
    ${alpha(theme.palette.primary.main, 0.95)} 0%,
    ${alpha(theme.palette.primary.dark, 0.95)} 100%
  )`,
  backdropFilter: 'blur(12px)',
  WebkitBackdropFilter: 'blur(12px)',
  boxShadow: theme.shadows[10],
  borderBottom: `1px solid ${alpha(theme.palette.divider, 0.1)}`,
  transition: 'all 0.5s cubic-bezier(0.16, 1, 0.3, 1)',
}));

const NavButton = styled(Button)(({ theme }) => ({
  position: 'relative',
  margin: theme.spacing(0, 1),
  fontWeight: 600,
  letterSpacing: '0.8px',
  padding: theme.spacing(1, 2),
  borderRadius: theme.shape.borderRadius,
  overflow: 'hidden',
  '&::before': {
    content: '""',
    position: 'absolute',
    bottom: 0,
    left: 0,
    width: '100%',
    height: '2px',
    background: theme.palette.secondary.main,
    transform: 'scaleX(0)',
    transformOrigin: 'right',
    transition: 'transform 0.5s cubic-bezier(0.22, 1, 0.36, 1)',
  },
  '&:hover::before': {
    transform: 'scaleX(1)',
    transformOrigin: 'left',
  },
  '&:hover': {
    transform: 'translateY(-2px)',
    boxShadow: `0 4px 12px ${alpha(theme.palette.secondary.main, 0.2)}`,
  },
  '&.active': {
    color: theme.palette.secondary.main,
    '&::before': {
      transform: 'scaleX(1)',
    },
  },
}));

const FloatingAvatar = styled(Avatar)(({ theme }) => ({
  transition: 'all 0.3s ease',
  boxShadow: theme.shadows[4],
  '&:hover': {
    transform: 'translateY(-4px) scale(1.05)',
    boxShadow: theme.shadows[10],
  },
}));

const SearchField = styled('div')(({ theme }) => ({
  position: 'relative',
  borderRadius: theme.shape.borderRadius * 2,
  backgroundColor: alpha(theme.palette.common.white, 0.15),
  '&:hover': {
    backgroundColor: alpha(theme.palette.common.white, 0.25),
  },
  marginRight: theme.spacing(2),
  marginLeft: 0,
  width: '100%',
  maxWidth: '300px',
  transition: 'all 0.3s ease',
  [theme.breakpoints.up('sm')]: {
    marginLeft: theme.spacing(3),
    width: 'auto',
  },
}));

const SearchIconWrapper = styled('div')(({ theme }) => ({
  padding: theme.spacing(0, 2),
  height: '100%',
  position: 'absolute',
  pointerEvents: 'none',
  display: 'flex',
  alignItems: 'center',
  justifyContent: 'center',
}));

const StyledInputBase = styled('input')(({ theme }) => ({
  color: 'inherit',
  '&::placeholder': {
    color: alpha(theme.palette.common.white, 0.7),
  },
  padding: theme.spacing(1, 1, 1, 0),
  paddingLeft: `calc(1em + ${theme.spacing(4)})`,
  transition: theme.transitions.create('width'),
  width: '100%',
  background: 'transparent',
  border: 'none',
  outline: 'none',
  fontSize: '0.875rem',
  fontWeight: 500,
}));

const Navbar = ({ darkMode, toggleDarkMode }) => {
  const [anchorEl, setAnchorEl] = useState(null);
  const [mobileMoreAnchorEl, setMobileMoreAnchorEl] = useState(null);
  const [scrolled, setScrolled] = useState(false);
  const [searchOpen, setSearchOpen] = useState(false);
  const searchRef = useRef(null);
  const controls = useAnimation();
  const theme = useTheme();
  const navigate = useNavigate();

  // Scroll handler with debounce
  useEffect(() => {
    const handleScroll = () => {
      const isScrolled = window.scrollY > 10;
      if (isScrolled !== scrolled) {
        setScrolled(isScrolled);
        controls.start(isScrolled ? 'scrolled' : 'normal');
      }
    };

    const debouncedScroll = debounce(handleScroll, 50);
    window.addEventListener('scroll', debouncedScroll);
    return () => window.removeEventListener('scroll', debouncedScroll);
  }, [scrolled, controls]);

  // Click outside search handler
  useEffect(() => {
    const handleClickOutside = (event) => {
      if (searchRef.current && !searchRef.current.contains(event.target)) {
        setSearchOpen(false);
      }
    };
    document.addEventListener('mousedown', handleClickOutside);
    return () => document.removeEventListener('mousedown', handleClickOutside);
  }, []);

  const handleProfileMenuOpen = (event) => {
    setAnchorEl(event.currentTarget);
  };

  const handleMobileMenuClose = () => {
    setMobileMoreAnchorEl(null);
  };

  const handleMenuClose = () => {
    setAnchorEl(null);
    handleMobileMenuClose();
  };

  const handleMobileMenuOpen = (event) => {
    setMobileMoreAnchorEl(event.currentTarget);
  };

  const handleLogout = () => {
    handleMenuClose();
    navigate('/login');
  };

  const toggleSearch = () => {
    setSearchOpen(!searchOpen);
  };

  const menuId = 'primary-search-account-menu';
  const renderMenu = (
    <Menu
      anchorEl={anchorEl}
      anchorOrigin={{
        vertical: 'bottom',
        horizontal: 'right',
      }}
      id={menuId}
      keepMounted
      transformOrigin={{
        vertical: 'top',
        horizontal: 'right',
      }}
      open={Boolean(anchorEl)}
      onClose={handleMenuClose}
      PaperProps={{
        elevation: 8,
        sx: {
          borderRadius: '16px',
          minWidth: '220px',
          overflow: 'visible',
          mt: 1.5,
          '&:before': {
            content: '""',
            display: 'block',
            position: 'absolute',
            top: 0,
            right: 14,
            width: 10,
            height: 10,
            bgcolor: 'background.paper',
            transform: 'translateY(-50%) rotate(45deg)',
            zIndex: 0,
          },
        },
      }}
    >
      <MenuItem 
        onClick={handleMenuClose} 
        component={Link} 
        to="/profile"
        sx={{
          '&:hover': {
            backgroundColor: alpha(theme.palette.primary.main, 0.1),
          },
        }}
      >
        <FloatingAvatar sx={{ mr: 2 }} />
        <Box>
          <Typography variant="subtitle1">John Doe</Typography>
          <Typography variant="caption" color="text.secondary">
            Premium Member
          </Typography>
        </Box>
      </MenuItem>
      <Divider />
      <MenuItem 
        onClick={handleMenuClose} 
        component={Link} 
        to="/settings"
        sx={{
          '&:hover': {
            backgroundColor: alpha(theme.palette.primary.main, 0.1),
          },
        }}
      >
        <SettingsIcon sx={{ mr: 2 }} fontSize="small" />
        Settings
      </MenuItem>
      <MenuItem 
        onClick={toggleDarkMode}
        sx={{
          '&:hover': {
            backgroundColor: alpha(theme.palette.primary.main, 0.1),
          },
        }}
      >
        {darkMode ? (
          <Brightness7 sx={{ mr: 2 }} fontSize="small" />
        ) : (
          <Brightness4 sx={{ mr: 2 }} fontSize="small" />
        )}
        {darkMode ? 'Light Mode' : 'Dark Mode'}
      </MenuItem>
      <Divider />
      <MenuItem 
        onClick={handleLogout}
        sx={{
          color: theme.palette.error.main,
          '&:hover': {
            backgroundColor: alpha(theme.palette.error.main, 0.1),
          },
        }}
      >
        <LogoutIcon sx={{ mr: 2 }} fontSize="small" />
        Logout
      </MenuItem>
    </Menu>
  );

  const mobileMenuId = 'primary-search-account-menu-mobile';
  const renderMobileMenu = (
    <Menu
      anchorEl={mobileMoreAnchorEl}
      anchorOrigin={{
        vertical: 'top',
        horizontal: 'right',
      }}
      id={mobileMenuId}
      keepMounted
      transformOrigin={{
        vertical: 'top',
        horizontal: 'right',
      }}
      open={Boolean(mobileMoreAnchorEl)}
      onClose={handleMobileMenuClose}
      PaperProps={{
        sx: {
          width: '80vw',
          maxWidth: '400px',
          borderRadius: '16px',
        },
      }}
    >
      <MenuItem>
        <SearchField fullWidth ref={searchRef}>
          <SearchIconWrapper>
            <Search />
          </SearchIconWrapper>
          <StyledInputBase
            placeholder="Search…"
            inputProps={{ 'aria-label': 'search' }}
          />
        </SearchField>
      </MenuItem>
      <Divider />
      <MenuItem component={Link} to="/" onClick={handleMobileMenuClose}>
        Dashboard
      </MenuItem>
      <MenuItem component={Link} to="/stock" onClick={handleMobileMenuClose}>
        Stock
      </MenuItem>
      <MenuItem component={Link} to="/finance" onClick={handleMobileMenuClose}>
        Finance
      </MenuItem>
      <MenuItem component={Link} to="/invoice" onClick={handleMobileMenuClose}>
        Invoices
      </MenuItem>
      <Divider />
      <MenuItem onClick={toggleDarkMode}>
        {darkMode ? 'Light Mode' : 'Dark Mode'}
        <Switch checked={darkMode} onChange={toggleDarkMode} sx={{ ml: 'auto' }} />
      </MenuItem>
    </Menu>
  );

  // Animation variants
  const variants = {
    scrolled: {
      height: '60px',
      backdropFilter: 'blur(20px)',
      boxShadow: theme.shadows[16],
    },
    normal: {
      height: '80px',
      backdropFilter: 'blur(12px)',
      boxShadow: theme.shadows[10],
    },
  };

  return (
    <>
      <motion.div
        animate={controls}
        initial="normal"
        variants={variants}
        style={{
          position: 'fixed',
          width: '100%',
          zIndex: theme.zIndex.appBar,
        }}
      >
        <GlassAppBar>
          <Toolbar sx={{ height: '100%' }}>
            {/* Mobile menu button */}
            <IconButton
              size="large"
              edge="start"
              color="inherit"
              aria-label="open drawer"
              sx={{ mr: 2, display: { xs: 'flex', md: 'none' } }}
              onClick={handleMobileMenuOpen}
            >
              <MenuIcon />
            </IconButton>

            {/* Logo/Brand */}
            <motion.div
              whileHover={{ scale: 1.05 }}
              whileTap={{ scale: 0.95 }}
              style={{ display: 'flex', alignItems: 'center' }}
            >
              <Typography
                variant="h6"
                noWrap
                component={Link}
                to="/"
                sx={{
                  mr: 2,
                  fontWeight: 800,
                  letterSpacing: '.15rem',
                  color: 'inherit',
                  textDecoration: 'none',
                  display: 'flex',
                  alignItems: 'center',
                }}
              >
                <motion.div
                  animate={{
                    rotate: scrolled ? 360 : 0,
                    scale: scrolled ? 0.8 : 1,
                  }}
                  transition={{ type: 'spring', stiffness: 200 }}
                  style={{
                    display: 'inline-block',
                    marginRight: '8px',
                    width: '32px',
                    height: '32px',
                    backgroundColor: theme.palette.secondary.main,
                    borderRadius: '8px',
                  }}
                />
                FinTrack
              </Typography>
            </motion.div>

            {/* Search - desktop */}
            <AnimatePresence>
              {searchOpen && (
                <motion.div
                  initial={{ opacity: 0, width: 0 }}
                  animate={{ opacity: 1, width: '300px' }}
                  exit={{ opacity: 0, width: 0 }}
                  transition={{ type: 'spring', stiffness: 300, damping: 30 }}
                  style={{ overflow: 'hidden' }}
                >
                  <SearchField ref={searchRef}>
                    <SearchIconWrapper>
                      <Search />
                    </SearchIconWrapper>
                    <StyledInputBase
                      placeholder="Search…"
                      inputProps={{ 'aria-label': 'search' }}
                      autoFocus
                    />
                  </SearchField>
                </motion.div>
              )}
            </AnimatePresence>

            <Box sx={{ flexGrow: 1 }} />

            {/* Desktop navigation */}
            <Box sx={{ display: { xs: 'none', md: 'flex' }, alignItems: 'center' }}>
              <Tooltip title="Search" arrow>
                <IconButton
                  size="large"
                  color="inherit"
                  onClick={toggleSearch}
                  sx={{ mr: 1 }}
                >
                  <Search />
                </IconButton>
              </Tooltip>

              <NavButton color="inherit" component={Link} to="/">
                Dashboard
              </NavButton>
              <NavButton color="inherit" component={Link} to="/stock">
                Stock
              </NavButton>
              <NavButton color="inherit" component={Link} to="/finance">
                Finance
              </NavButton>
              <NavButton color="inherit" component={Link} to="/invoice">
                Invoices
              </NavButton>

              <Tooltip title="Notifications" arrow>
                <IconButton
                  size="large"
                  color="inherit"
                  sx={{ mx: 1, position: 'relative' }}
                >
                  <Badge badgeContent={4} color="secondary">
                    <Notifications />
                  </Badge>
                </IconButton>
              </Tooltip>

              <Tooltip title="Toggle dark mode" arrow>
                <IconButton
                  size="large"
                  color="inherit"
                  onClick={toggleDarkMode}
                  sx={{ mx: 1 }}
                >
                  {darkMode ? <Brightness7 /> : <Brightness4 />}
                </IconButton>
              </Tooltip>

              <IconButton
                size="large"
                edge="end"
                aria-label="account of current user"
                aria-controls={menuId}
                aria-haspopup="true"
                onClick={handleProfileMenuOpen}
                color="inherit"
                sx={{ ml: 1 }}
              >
                <motion.div whileHover={{ scale: 1.1 }} whileTap={{ scale: 0.9 }}>
                  <FloatingAvatar
                    alt="User Avatar"
                    src="/static/images/avatar/1.jpg"
                  />
                </motion.div>
              </IconButton>
            </Box>
          </Toolbar>
        </GlassAppBar>
      </motion.div>

      {renderMobileMenu}
      {renderMenu}

      {/* Add this to prevent content from being hidden behind the fixed navbar */}
      <Toolbar sx={{ height: scrolled ? '60px' : '80px' }} />

      {/* Scroll to top button */}
      <AnimatePresence>
        {scrolled && (
          <motion.div
            initial={{ opacity: 0, y: 20 }}
            animate={{ opacity: 1, y: 0 }}
            exit={{ opacity: 0, y: 20 }}
            style={{
              position: 'fixed',
              bottom: '32px',
              right: '32px',
              zIndex: theme.zIndex.speedDial,
            }}
          >
            <Tooltip title="Scroll to top" arrow>
              <IconButton
                onClick={() => window.scrollTo({ top: 0, behavior: 'smooth' })}
                sx={{
                  backgroundColor: theme.palette.primary.main,
                  color: theme.palette.primary.contrastText,
                  boxShadow: theme.shadows[10],
                  '&:hover': {
                    backgroundColor: theme.palette.primary.dark,
                  },
                }}
                size="large"
              >
                <KeyboardArrowUp />
              </IconButton>
            </Tooltip>
          </motion.div>
        )}
      </AnimatePresence>
    </>
  );
};

// Helper function
function debounce(func, wait) {
  let timeout;
  return function executedFunction(...args) {
    const later = () => {
      clearTimeout(timeout);
      func(...args);
    };
    clearTimeout(timeout);
    timeout = setTimeout(later, wait);
  };
}

export default Navbar;
